pub fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let x_len = x.len();
    let y_len = y.len();

    // X has y_len rows, each row equals x
    let mut x_grid: Vec<Vec<f32>> = Vec::with_capacity(y_len);
    // Y has y_len rows, each row is y[i] repeated x_len times
    let mut y_grid: Vec<Vec<f32>> = Vec::with_capacity(y_len);

    for &yi in y.iter() {
        x_grid.push(x.clone());
        y_grid.push(vec![yi; x_len]);
    }

    (x_grid, y_grid)
}